const D=[
  {n:'let vs const',c:'basics',d:'Two ways to make a named box for a value. One kind can be given a new value later. The other kind is locked once you fill it.',p:'Use const everywhere, and only use let for values that really need to change later.',x:'const name = "Ada"; let score = 0; score = 10;'},
  {n:'Data Types',c:'basics',d:'The different kinds of values in JavaScript, like text, numbers, yes or no, lists, and bundles of labeled values.',p:'Print what kind of value each of these is, because I think text and numbers are getting mixed up.',x:'typeof "hi" // "string"   typeof 42 // "number"'},
  {n:'=== vs ==',c:'basics',d:'Two ways to ask "are these the same?" The strict one says the text "5" and the number 5 are different. The loose one says they match.',p:'Use the strict three-equals check everywhere so text and numbers never match by accident.',x:'"5" == 5 // true   "5" === 5 // false'},
  {n:'Truthy & Falsy',c:'basics',d:'When your code asks a yes-or-no question about a value, every value counts as one or the other. Things like 0, empty text, and nothing at all count as no.',p:'This check gets skipped when it should not. Could the value be 0 or empty text and count as false?',x:'if (cart.length) { ... } // 0 items counts as false, so this is skipped'},
  {n:'Template Literals',c:'basics',d:'Text wrapped in backticks, the slanted quote mark `. Inside it you can drop a named value straight into the sentence using ${ }.',p:'Write this message as one piece of text with the name and count dropped straight in. Do not glue pieces together with plus signs.',x:'const msg = `Hi ${name}, you have ${count} items`;'},
  {n:'Ternary',c:'basics',d:'A one-line way to pick between two values. You write a yes-or-no question, then a question mark, then the two choices.',p:'Make this either-or choice a one-line ternary. For anything bigger, keep the longer spelled-out version.',x:'const label = count === 1 ? "item" : "items";'},
  {n:'Type Conversion',c:'basics',d:'Turning one kind of value into another, like the text "5" into the number 5. Skip it and "5" + 1 gives you "51".',p:'Turn what the user typed into a real number before you do any math with it.',x:'Number("5") + 1 // 6   "5" + 1 // "51"'},
  {n:'console.log',c:'basics',d:'A line you add to your code that prints a value into the browser\'s message panel, so you can see what is really going on.',p:'Add labeled console.logs around the lines that look wrong, so I can paste you what they print.',x:'console.log("cart before save:", cart);'},
  {n:'for...of Loops',c:'basics',d:'A way to go through a list one item at a time and run the same steps on every item, without keeping count yourself.',p:'Go through each item in the cart with a for...of loop and add its price to the total.',x:'for (const item of cart) { total += item.price; }'},
  {n:'Arrow Functions',c:'functions',d:'A shorter way to write a reusable block of code. You list the inputs, then =>, then what comes out.',p:'Write these small reusable pieces of code as short arrow functions, and make each one do just one job.',x:'const double = (n) => n * 2;'},
  {n:'Parameters',c:'functions',d:'The named inputs a reusable block of code asks for, listed inside its round brackets. They are the ingredients it needs.',p:'What inputs does this block of code need, and what happens if I leave one out?',x:'function greet(name) { ... }   greet("Sam");'},
  {n:'Return Values',c:'functions',d:'What a block of code hands back to you when it finishes. If it hands back nothing, you get "undefined", which means no value.',p:'This result shows up as undefined. Does the code actually hand back the total at the end?',x:'const sum = (a, b) => { return a + b; };'},
  {n:'Default Parameters',c:'functions',d:'Backup values for inputs. If whoever runs the code leaves an input out, the backup is used automatically.',p:'Give each input a backup value, so this code still works when I leave one out.',x:'function greet(name = "friend") { ... }'},
  {n:'Callbacks',c:'functions',d:'A piece of code you hand to another piece of code so it can be run later, like when a button is clicked or a timer ends.',p:'Which callback runs when this button is clicked? Show me where it gets hooked up.',x:'button.addEventListener("click", handleClick);'},
  {n:'Scope',c:'functions',d:'The area of your code where a named value can be seen. One made inside curly braces cannot be used outside them.',p:'The error says this name is not defined. Was it created somewhere this line of code cannot see?',x:'if (ok) { let msg = "hi"; }  msg // ReferenceError'},
  {n:'Closures',c:'functions',d:'A piece of code remembers the values it could see when it was made. It keeps them, even after the code around it has finished.',p:'This button code keeps using an old value. Explain the closure that causes it, then fix it.',x:'const counter = () => { let n = 0; return () => ++n; };'},
  {n:'Pure Functions',c:'functions',d:'Code that always gives the same answer for the same inputs and never changes anything outside itself. Easy to test and trust.',p:'Make this a pure function that gives back a new value and changes nothing outside itself.',x:'const withTax = (price) => price * 1.21;'},
  {n:'Array Basics',c:'arrays',d:'An ordered list of values kept under one name. Counting starts at 0, so the first item is number 0.',p:'The wrong item shows up. Check the position numbers. Counting starts at 0, so the last one is one less than the number of items.',x:'const tags = ["js", "css"]; tags[0] // "js"'},
  {n:'push & pop',c:'arrays',d:'One adds an item to the end of a list. The other takes the last item off. Both change the list itself.',p:'Add the new item to the end of the cart list, and take the last one off when I click undo.',x:'cart.push(item);  const last = cart.pop();'},
  {n:'map',c:'arrays',d:'Changes every item in a list the same way and gives you a brand new list. The old list is left alone.',p:'Use map to turn this list of prices into a new list with tax added to each one.',x:'prices.map((p) => p * 1.21)'},
  {n:'filter',c:'arrays',d:'Keeps only the items that pass your test and gives you a new, shorter list.',p:'Give me a new list with only the to-dos that are not done yet.',x:'todos.filter((t) => !t.done)'},
  {n:'reduce',c:'arrays',d:'Boils a whole list down to a single value, like a total, the biggest number, or a count.',p:'Add up all the prices into one total with reduce, and explain it to me line by line.',x:'prices.reduce((sum, p) => sum + p, 0)'},
  {n:'find',c:'arrays',d:'Gives you the first item in a list that passes your test. If nothing passes, you get "undefined", which means no value.',p:'Get the one user whose id is 7, and handle the case where no user matches.',x:'users.find((u) => u.id === 7)'},
  {n:'includes',c:'arrays',d:'A yes or no check. Is this value somewhere in the list? It also works for a bit of text inside longer text.',p:'Check if "admin" is in this user\'s list of roles. Do not compare against each role one by one.',x:'roles.includes("admin") // true or false'},
  {n:'sort',c:'arrays',d:'Puts a list in order. Watch out, because it compares items as text unless you tell it how, so 10 lands before 9.',p:'Sort these scores from lowest to highest as real numbers, so 10 does not land before 9.',x:'scores.sort((a, b) => a - b)'},
  {n:'forEach',c:'arrays',d:'Runs your code once on every item in a list. It just does the work and does not give you a new list back.',p:'Use forEach to print the message from every error in this list.',x:'errors.forEach((e) => console.log(e.message));'},
  {n:'Object Literals',c:'objects',d:'A bundle of labeled values written inside curly braces. It keeps related facts together, like a person\'s name and age.',p:'Group these loose values into one user object with a clear label on each.',x:'const user = { name: "Ada", age: 36 };'},
  {n:'Dot vs Bracket',c:'objects',d:'Two ways to read one value out of a bundle. One is for when you can type the label yourself. The other is for when the label is only known while the app runs.',p:'The label I need changes while the app runs, so read it with square brackets, not a dot.',x:'user.name   user["name"]   user[field]'},
  {n:'Destructuring',c:'objects',d:'Pulls several values out of a bundle or list and gives each one its own name, all in one line.',p:'Pull just the name and age out of the user bundle, in one line, at the top of this code.',x:'const { name, age } = user;'},
  {n:'Spread Operator',c:'objects',d:'Three dots that pour everything from one list or bundle into a new one. Handy for making a copy with one thing changed.',p:'Make a copy of user with the age changed to 37 using the three dots, and leave the original alone.',x:'const updated = { ...user, age: 37 };'},
  {n:'Optional Chaining',c:'objects',d:'A question mark and a dot that let you reach deep into data safely. If a piece is missing you get an empty value and not a crash.',p:'It crashes with "cannot read properties of undefined". Add optional chaining where the data might be missing.',x:'user?.address?.city // undefined, not a crash'},
  {n:'JSON.parse',c:'objects',d:'Saved or sent data arrives as one long piece of text. This turns it back into a list or bundle your code can work with.',p:'The saved cart comes back as text. Turn it back into real data before we use it.',x:'const user = JSON.parse(saved);'},
  {n:'Object.keys',c:'objects',d:'Gives you a list of every label in a bundle of data, so you can go through them one by one.',p:'Go through every label in this settings object and print each one with its value.',x:'Object.keys(user) // ["name", "age"]'},
  {n:'The this Keyword',c:'objects',d:'A special word that code inside a bundle uses to mean "the bundle I belong to". Which bundle that is depends on how the code was run, which causes bugs.',p:'Explain what "this" points to on that exact line, and why it is not the user object.',x:'const user = { name: "Ada", hi() { return this.name; } };'},
  {n:'Promises',c:'async',d:'A placeholder for a value that is not ready yet, like the ticket you get while your order is being made. Later it either delivers the data or tells you it failed.',p:'This gives me a Promise and not the data. Where should we wait for it, and where do we handle it failing?',x:'fetch(url) // a Promise, not the data yet, so await it'},
  {n:'async/await',c:'async',d:'Two special words that make slow code read top to bottom. One marks the code as slow. The other pauses it until the answer arrives.',p:'Write this with async and await so each step holds on until the one before it has finished.',x:'const res = await fetch(url); const data = await res.json();'},
  {n:'fetch',c:'async',d:'The browser\'s built-in way to ask another computer on the internet for data, or to send data to it. The answer takes a moment to arrive.',p:'Load the to-dos from our to-dos web address. Check the answer came back fine, then turn it into data before using it.',x:'const res = await fetch("/api/todos");'},
  {n:'try/catch',c:'async',d:'Wraps risky code so that if it fails, a backup block runs and the app does not crash.',p:'Wrap the save in a try/catch and show the user a clear message if it fails.',x:'try { await save(); } catch (e) { showError(e); }'},
  {n:'setTimeout',c:'async',d:'Runs a piece of code once, after a delay you choose, counted in thousandths of a second.',p:'Hide the banner after 3 seconds, and cancel that timer if the user closes it first.',x:'setTimeout(() => banner.remove(), 3000);'},
  {n:'Promise.all',c:'async',d:'Starts several slow jobs at the same time and waits until every one is finished. Faster than doing them one by one.',p:'These two slow jobs do not need each other. Run them at the same time with Promise.all.',x:'const [a, b] = await Promise.all([getA(), getB()]);'},
  {n:'The Event Loop',c:'async',d:'JavaScript does one thing at a time. Slow jobs wait in a line and only run once the current job is done. This is what manages that line.',p:'These run in an order I did not expect. Walk me through what runs first, second and third, and why.',x:'log(1); setTimeout(() => log(2), 0); log(3) // prints 1 3 2'},
  {n:'.then Chains',c:'async',d:'The older way to deal with a value that arrives later. You line up steps, and each step passes its result to the next one.',p:'This has .then after .then. Rewrite it so it is easier to read, and keep it working the same.',x:'fetch(url).then((r) => r.json()).then(render);'},
  {n:'querySelector',c:'dom',d:'Finds the first thing on the page that fits a short description you give it, like its name or its kind, so your code can work with it.',p:'Grab the Save button by its id, and check it exists before using it.',x:'const btn = document.querySelector("#save");'},
  {n:'addEventListener',c:'dom',d:'Tells the page to run your code when something happens to part of the page, like a click, a key press, or a form being sent.',p:'Use addEventListener to run my code when the form is sent. Keep that in the JavaScript file, not mixed into the page itself.',x:'form.addEventListener("submit", handleSubmit);'},
  {n:'classList',c:'dom',d:'Lets your code put a style label on part of the page, take it off, or switch it. The styles file then decides how that label looks.',p:'Switch an "open" style label on and off on the popup. Keep how it looks in the styles file, not written into the code.',x:'modal.classList.toggle("open");'},
  {n:'createElement',c:'dom',d:'Builds a brand new piece of the page in code, like a list item, ready to fill in and add to the page.',p:'Make a new list item for each to-do, put its text in, then add it to the list on the page.',x:'const li = document.createElement("li");'},
  {n:'textContent vs innerHTML',c:'dom',d:'Two ways to put words on the page. One shows them exactly as typed, which is safe. The other lets them act as part of the page, so a stranger could slip in harmful code.',p:'Show the user\'s name with textContent, not innerHTML, so nobody can sneak code into the page.',x:'el.textContent = userName; // safe with any input'},
  {n:'input.value',c:'dom',d:'Where you read what the user typed into a box on the page. It always comes to you as text, even when they typed a number.',p:'Read what was typed in the quantity box and turn it into a number before doing the math.',x:'const qty = Number(input.value);'},
  {n:'The Event Object',c:'dom',d:'A bundle of details your code is handed when something happens on the page. It says what was clicked and lets you stop the usual behavior.',p:'The page reloads when I send the form. Use the event details to stop that, right at the start of the form code.',x:'form.addEventListener("submit", (e) => { e.preventDefault(); });'},
  {n:'dataset',c:'dom',d:'Lets your code read small hidden notes you attached to part of the page, like the number of the item it shows.',p:'Store each to-do\'s id on its list item with data-id, and read it back when the item is clicked.',x:'<li data-id="7">  →  li.dataset.id // "7"'},
  {n:'localStorage',c:'patterns',d:'A small notebook in the browser where your app can save things, so they are still there after a refresh. It only holds text.',p:'Save the cart in the browser so it survives a refresh, and handle the first visit when nothing is saved yet.',x:'localStorage.setItem("cart", JSON.stringify(cart));'},
  {n:'Array of Objects',c:'patterns',d:'The most common shape for app data. A list where every item is a bundle with the same labels, like id, text, and done.',p:'Keep the to-dos as a list where each one has an id, text, and done, so we can search and filter them easily.',x:'const todos = [{ id: 1, text: "ship", done: false }];'},
  {n:'Guard Clauses',c:'patterns',d:'Checks at the very top of a block of code that deal with the bad cases first and leave early, so the rest stays simple.',p:'Check for a missing user at the top and leave early. Do not wrap everything in one big if.',x:'if (!user) return;  // from here on we know there is a user'},
  {n:'Short-Circuiting',c:'patterns',d:'The "or" sign (||) takes the first value that counts as a yes. The "and" sign (&&) stops at the first one that counts as a no. Handy for a backup value when one is missing.',p:'If the name is empty, use "Anonymous". Also tell me if there is a safer way when a real value like 0 could be mistaken for empty.',x:'const name = input || "Anonymous";'},
  {n:'Debouncing',c:'patterns',d:'Waiting until the user has stopped typing for a moment before doing heavy work like a search, so it does not run on every key press.',p:'Debounce the search box so it only runs once I stop typing for 300 milliseconds.',x:'clearTimeout(t); t = setTimeout(search, 300);'},
  {n:'State Then Render',c:'patterns',d:'Keep the real data in one place. After every change, redraw the screen from that data, so the two never disagree.',p:'Keep all the app data in one place. After every change, redraw the screen from that data with one single piece of code.',x:'state.todos.push(todo); render();'},
  {n:'Copy, Not Mutate',c:'patterns',d:'Changing shared data directly causes confusing bugs. Make a fresh version with your change in it and use that one.',p:'Give me a new list with the to-do added. Do not change the old list.',x:'const next = [...todos, newTodo];'},
  {n:'npm',c:'tooling',d:'The tool that downloads ready-made code other people wrote into your project. It also runs your project\'s commands.',p:'Before we download more ready-made code, can plain JavaScript do this just as well?',x:'npm install dayjs  →  import dayjs from "dayjs"'},
  {n:'package.json',c:'tooling',d:'The file that describes your project. It lists its name, the outside code it needs, and the shortcut commands you can run.',p:'Add a shortcut command called "dev" to package.json, so I can start the project by typing npm run dev.',x:'"scripts": { "dev": "vite" }  →  npm run dev'},
  {n:'Modules',c:'tooling',d:'Splitting your code across several files. Each file hands out the parts it wants to share, and other files borrow them. No more one giant file.',p:'Split this big file into smaller files, one per job, and import what each one needs.',x:'import { saveCart } from "./storage.js";'},
  {n:'DevTools',c:'tooling',d:'A hidden panel built into the browser on your computer. It shows error messages and what your page asked the internet for, and lets you look inside any part of the page.',p:'Here is the red error from the Console tab and the failed request from the Network tab. What is wrong?',x:'Right-click → Inspect. Red text in the Console is where to start.'},
  {n:'The Dev Server',c:'tooling',d:'A small program on your own computer that shows your site in the browser and refreshes the page each time you save.',p:'My page breaks when I open the file directly. Set up a dev server so I can run it on my own computer, and tell me which one you picked.',x:'npm create vite@latest  →  npm run dev  →  localhost:5173'},
];

